import{_ as r,c as o,o as e,ae as n}from"./chunks/framework.D6wf4lw6.js";const f=JSON.parse('{"title":"聲音包-預設3種消音填充","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/基础定制/声音包.md","filePath":"zh-HK/基础定制/声音包.md"}'),s={name:"zh-HK/基础定制/声音包.md"};function a(l,t,g,i,d,h){return e(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="聲音包-預設3種消音填充" tabindex="-1">聲音包-預設3種消音填充 <a class="header-anchor" href="#聲音包-預設3種消音填充" aria-label="Permalink to &quot;聲音包-預設3種消音填充&quot;">​</a></h1><p>機械式鍵盤的填充物是一個多層級的消音系統。 <br>一般分為【夾心棉】【軸下墊】【底棉】，每一層都有其明確的作用，共同協作以消除雜音、統一手感和塑造聲音。</p><ul><li><strong>基礎消音層（結構消音）</strong>：<strong>底棉</strong> 和 <strong>夾心棉</strong>。它們主要負責處理因鍵盤結構產生的<strong>空腔音</strong>和<strong>迴聲</strong>，解決了鍵盤聽起來“塑料”和“空洞”的根本問題。</li><li><strong>進階消音層（聲音來源消音）</strong>：<strong>軸下墊</strong>。直接作用於聲音的源頭－軸體，負責消除軸體撞擊雜音，並塑造核心的按鍵音色。</li></ul><h2 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h2><h3 id="各填充物作用詳解" tabindex="-1">各填充物作用詳解 <a class="header-anchor" href="#各填充物作用詳解" aria-label="Permalink to &quot;各填充物作用詳解&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">部件名稱</th><th style="text-align:left;">位置</th><th style="text-align:left;">主要作用</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>夾心棉</strong></td><td style="text-align:left;">定位板與PCB之間</td><td style="text-align:left;">1. <strong>消除空腔音</strong>：填充定位板與PCB之間的主要空腔，吸收按鍵衝擊產生的振動和迴聲，防止聲音在殼體內迴盪。 <br>2. <strong>統一聲音</strong>：使鍵盤各區域（特別是大鍵與小鍵）的按鍵聲音更加一致、均勻。 <br>3. <strong>過濾高頻噪音</strong>：吸收並削弱刺耳的高頻振動，讓鍵盤的整體音色更純粹、低沉。</td></tr><tr><td style="text-align:left;"><strong>軸下墊</strong></td><td style="text-align:left;">PCB與軸體底部之間，緊貼PCB</td><td style="text-align:left;">1. <strong>消除軸體雜音</strong>：這是最關鍵的作用。它能吸收軸體內部金屬彈片振動和軸體觸底時撞擊PCB所產生的「叮叮」聲等高頻噪音。 <br>2. <strong>塑造核心音色</strong>：對軸體本身的聲音進行“提純”，是形成“麻將音”、“石子音”等所謂Hifi音的關鍵部件。 <br>3. <strong>改變觸底手感</strong>：使軸體觸底的感覺變得更柔和、更“肉”，減少硬碰硬的撞擊感。</td></tr><tr><td style="text-align:left;"><strong>底棉</strong></td><td style="text-align:left;">鍵盤外殼的底部，PCB之下</td><td style="text-align:left;">1. <strong>消除最大空腔音</strong>：填充PCB與底殼之間的巨大空間，這是鍵盤內部最大的共鳴腔，底棉能最有效地消除低沉、空洞的迴響。 <br>2. <strong>增加穩重感</strong>：透過填充使鍵盤內部結構更緊密，敲擊時感覺整體更紮實、不鬆散。</td></tr></tbody></table><hr><h3 id="系統層級作用總結" tabindex="-1">系統層級作用總結 <a class="header-anchor" href="#系統層級作用總結" aria-label="Permalink to &quot;系統層級作用總結&quot;">​</a></h3><p>可以將這些填充物理解為一個協同工作的團隊：</p><ul><li><strong>過猶不及</strong>：填充過厚或過硬的棉會<strong>增加鍵盤內部的壓力</strong>，可能導致PCB彎曲、軸體引腳接觸不良、甚至使Gasket結構的&quot;軟彈&quot;手感消失。務必選擇合適厚度的填充物。</li><li><strong>聲音是系統工程</strong>：填充物只是&quot;淨化&quot;聲音，而鍵盤的最終音色是由 <strong>軸體（核心聲源） + 定位板（調音板） + 填充物（消音系統） + 鍵帽（共鳴腔） + 結構（傳播路徑）</strong> 共同決定的。不要期待只加一張軸下墊就能讓青軸變成靜音紅軸。</li><li><strong>手感影響</strong>：<strong>軸下墊</strong>會明顯讓觸底感變得更&quot;軟&quot;更&quot;肉&quot;，如果你喜歡非常乾脆利落的觸底反饋（如游戲玩家），可能需要選擇更薄的軸下墊或直接不加。</li></ul><blockquote><p><strong>核心要點</strong>：填充物的終極目的是 <strong>「淨化」聲音</strong>，而不是無中生有地創造聲音。它們透過吸收不必要的振動和雜音，讓軸體、定位板和鍵帽本身產生的乾淨、悅耳的基礎聲音得以清晰地展現出來，從而提升打字聽覺體驗的整體質感。</p></blockquote>',11)])])}const _=r(s,[["render",a]]);export{f as __pageData,_ as default};
